SELECT 'resultado' AS tipo, COUNT(*) AS equipos FROM public.teams WHERE school_id = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee' AND is_demo = true AND name IN ('SPRINKLES','BUTTERFLY','BOMBSQUAD','LEGENDS','FIRESQUAD','BOMBSHELLS');
SELECT 'resultado' AS tipo, COUNT(*) AS atletas FROM public.children WHERE school_id = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee' AND is_demo = true AND team_id IN (SELECT id FROM public.teams WHERE school_id = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee' AND is_demo = true AND name IN ('SPRINKLES','BUTTERFLY','BOMBSQUAD','LEGENDS','FIRESQUAD','BOMBSHELLS'));

